<?php require "db.php"; $rows=$conn->query("SELECT booking_id, passenger_id, flight_id, airport_id, booking_date, seat_number, travel_class, passenger_count, age_group, gender, status, created_at FROM bookings ORDER BY booking_id DESC"); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking List</title><link rel="stylesheet" href="style.css"></head><body><?php require "header.php"; ?><main class="container">
<div class="page-head"><div class="eyebrow">Database Records</div><h1>Booking List</h1><p>These records are read directly from the FLY Air MySQL database in XAMPP.</p></div>
<div class="panel panel-dark"><div class="table-wrap"><table class="table"><tr><th>Booking Id</th><th>Passenger Id</th><th>Flight Id</th><th>Airport Id</th><th>Booking Date</th><th>Seat Number</th><th>Travel Class</th><th>Passenger Count</th><th>Age Group</th><th>Gender</th><th>Status</th><th>Created At</th></tr><?php while($r=$rows->fetch_assoc()): ?><tr><td><?=e($r['booking_id'])?></td><td><?=e($r['passenger_id'])?></td><td><?=e($r['flight_id'])?></td><td><?=e($r['airport_id'])?></td><td><?=e($r['booking_date'])?></td><td><?=e($r['seat_number'])?></td><td><?=e($r['travel_class'])?></td><td><?=e($r['passenger_count'])?></td><td><?=e($r['age_group'])?></td><td><?=e($r['gender'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endwhile;?></table></div></div>
</main><?php require "footer.php"; ?></body></html>